package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 998244353

var factorial, invFactorial []int64

func power(a, k int64) int64 {
	result := int64(1)
	for k > 0 {
		if k&1 == 1 {
			result = result * a % mod
		}
		a = a * a % mod
		k >>= 1
	}
	return result
}

func choose(n, k int) int64 {
	return factorial[n] * invFactorial[k] % mod * invFactorial[n-k] % mod
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var n int
	var k int64
	fmt.Fscan(in, &n, &k)

	if k >= int64(n) {
		fmt.Fprintln(out, 0)
		return
	}

	c := n - int(k)
	factorial = make([]int64, 2*n)
	invFactorial = make([]int64, 2*n)

	f := int64(1)
	for i := 0; i < 2*n; i++ {
		factorial[i] = f
		invFactorial[i] = power(f, mod-2)
		f = f * int64(i+1) % mod
	}

	var ans int64
	for a := 1; a <= c; a++ {
		x := power(int64(a), int64(n)) * choose(c, a) % mod
		if (c-a)%2 == 0 {
			ans += x
		} else {
			ans -= x
		}
	}

	ans %= mod
	if ans < 0 {
		ans += mod
	}

	ans = ans * choose(n, c) % mod
	if k > 0 {
		ans = ans * 2 % mod
	}

	fmt.Fprintln(out, ans)
}

